import json,numpy as np,time
from scipy.optimize import linprog
D=json.load(open('kaggle_tasks_data/task012.json')); E=[e for v in D.values() for e in v]
def oh(g):
 a=np.zeros((10,30,30),np.int8)
 for r,row in enumerate(g):
  for c,v in enumerate(row):a[v,r,c]=1
 return a
XY=[(oh(e['input']),oh(e['output'])) for e in E]
def dataset(h,w,pt,pl,ks):
 seen={}
 for x,y in XY:
  z=np.pad(x,((0,0),(pt,h-1-pt),(pl,w-1-pl)))
  for k in ks:
   # sliding patches for same channel
   p=np.lib.stride_tricks.sliding_window_view(z[k],(h,w)).reshape(900,h*w)
   yy=y[k].reshape(-1)
   for row,label in zip(p,yy):
    q=np.packbits(row).tobytes(); old=seen.get(q)
    if old is not None and old"'!=label: return None,None
    seen[q]=int(label)
 X=np.unpackbits(np.frombuffer(b'"''.join(seen),np.uint8)).reshape(len(seen),-1)[:,:h*w].astype(float)
 Y=np.fromiter(seen.values(),np.int8)
 return X,Y
def fit(h,w,pt,pl,ks):
 X,Y=dataset(h,w,pt,pl,ks)
 if X is None:return False,'conflict'
 pos=X[Y==1];neg=X[Y==0]
 A=np.r_[-np.c_[pos,np.ones(len(pos))],np.c_[neg,np.ones(len(neg))]]
 b=np.r_[-np.ones(len(pos)),np.zeros(len(neg))]
 res=linprog(np.zeros(h*w+1),A_ub=A,b_ub=b,bounds=[(None,None)]*(h*w+1),method='highs')
 return res.success,(len(X),len(pos),None if not res.success else (np.max(abs(res.x)),np.count_nonzero(abs(res.x)>1e-8)))
for h,w in [(7,7),(7,8),(8,7),(7,9),(9,7),(8,8),(6,10),(10,6),(7,10),(10,7),(8,9)]:
 for pt in sorted(set([(h-1)//2,h//2])):
  for pl in sorted(set([(w-1)//2,w//2])):
   t=time.time(); a=fit(h,w,pt,pl,range(1,10)); b=fit(h,w,pt,pl,[0]); print((h,w,pt,pl),'fg',a,'bg',b,'sec',round(time.time()-t,2),flush=True)
